    cols = [c[1] for c in con.execute(f'PRAGMA table_info("{t}")')]
    for c in cols:
        if c in ('created_by_session','session_id','session'):
            sess_cols[t] = c
            break
print(f"tables carrying a session stamp: {len(sess_cols)} of {len(tabs)}\n")
